import requestsimport osimport jsonimport streamlit as st from bs4 import BeautifulSoupfrom dotenv import load_dotenvfrom openai import OpenAIfrom google.cloud import translate_v2 as translatefrom config import model, linkSysPrompt, brochureSysPrompt, translateSysPrompt# Headers for requestsheaders = { "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/117.0.0.0 Safari/537.36"}def loadAPIKey():    load_dotenv(override=True)    api_key = os.getenv('OPENAI_API_KEY')    if api_key and api_key.startswith('sk-proj-') and len(api_key)>10:        print("API key looks good so far")        return api_key    else:        print("There might be a problem with your API key? Please visit the troubleshooting notebook!")        return Noneclass Website:        def __init__(self, url):        self.url = url        try:            response = requests.get(url, headers=headers, timeout=10)            response.raise_for_status()        except requests.exceptions.RequestException as e:            print(f"Failed to fetch {url}: {e}")            self.body = b""            self.title = f"Failed to load {url}"            self.text = ""            self.links = []            return                self.body = response.content        soup = BeautifulSoup(self.body, 'html.parser')        self.title = soup.title.string if soup.title else "No title found"        if soup.body:            for irrelevant in soup.body(["script", "style", "img", "input"]):                irrelevant.decompose()            self.text = soup.body.get_text(separator="\n", strip=True)        else:            self.text = ""        links = [link.get('href') for link in soup.find_all('a')]        self.links = [link for link in links if link]    def getContents(self):        return f"Webpage Title:\n{self.title}\nWebpage Contents:\n{self.text}\n\n"    def getLinksUserPrompt(website):    user_prompt = f'Here is the list of links on the website of {website.url} - '    user_prompt += "please decide which of these are relevant web links for a brochure about the company, respond with the full https URL in JSON format. Do not include Terms of Service, Privacy, email links.\n"    user_prompt += "Links (some might be relative links):\n"    user_prompt += "\n".join(website.links)    return user_promptdef getLinks(url):    website = Website(url)    response = openai.chat.completions.create(        model=model,        messages=[            {"role": "system", "content": linkSysPrompt},            {"role": "user", "content": getLinksUserPrompt(website)}      ],        response_format={"type": "json_object"}    )    result = response.choices[0].message.content    return json.loads(result)def getAllContent(url):    result = "Landing page:\n"    result += Website(url).getContents()    links = getLinks(url)    print("Found links:", links)    for link in links["links"]:        result += f"\n\n{link['type']}\n"        result += Website(link["url"]).getContents()    return resultdef getBrochureUserPrompt(companyName, url):    user_prompt = f"You are looking at a company called: {companyName}\n"    user_prompt += f"Here are the contents of its landing page and other relevant pages; use this information to build a short brochure of the company in markdown.\n"    user_prompt += getAllContent(url)    user_prompt = user_prompt[:5_000]     return user_promptdef createBrochure(companyName, url):    stream = openai.chat.completions.create(        model=model,        messages=[            {"role": "system", "content": brochureSysPrompt},            {"role": "user", "content": getBrochureUserPrompt(companyName, url)}          ],        stream=True    )        return streamdef streamData(stream,language):    brochure = ""    placeholder = st.empty()    buffer = []  # hold streamed content before rendering       for chunk in stream:        if chunk.choices and chunk.choices[0].delta.content:            token = chunk.choices[0].delta.content                        if token.strip().startswith("```"):                    continue                        if "```" in token:                token = token.replace("```", "")                            buffer.append(token)            brochure = ''.join(buffer)            brochure = brochure.replace("```markdown", "").replace("```", "").strip()            placeholder.markdown(brochure, unsafe_allow_html=True)             return brochure            def translateBrochure(borchure, language):    userPrompt = f"Please translate the following brochure into {language}.\n\n{borchure[:5_000]}"    stream = openai.chat.completions.create(        model=model,        messages=[            {"role": "system", "content": translateSysPrompt},            {"role": "user", "content": userPrompt}        ],         stream=True    )        return stream    def getSupportedLanguages():    url = "https://libretranslate.com/languages"    response = requests.get(url)    if response.status_code == 200:        languages = response.json()        return [lang['name'] for lang in languages if lang['name'].lower() != "english"]    else:        st.error("Failed to fetch languages.")        return []        # Initialize OpenAI apiKey = loadAPIKey()openai = OpenAI(api_key=apiKey)# Fetch available languages dynamically    languages = getSupportedLanguages()    # --- Streamlit UI ---st.title("📄 Company Brochure Generator")with st.form("inputForm"):    companyName = st.text_input("Company Name", value="Hugging Face")    webURL = st.text_input("Company Website URL", value="https://huggingface.co")    submitted = st.form_submit_button("Generate Brochure")if submitted:    with st.spinner("Generating brochure... this might take a moment ⏳"):        try:            brochureStream = createBrochure(companyName, webURL)            st.session_state['brochureStream'] = brochureStream            st.markdown("### 📝 Generated Brochure\n")            brochure = streamData(brochureStream, "")            st.session_state['brochure'] = brochure            st.success("✅ Brochure generation complete!")        except Exception as e:            st.error(f"Something went wrong during generation: {e}")            # After brochure is generated and storedif 'brochure' in st.session_state:    brochureStream = st.session_state['brochureStream']    brochure = st.session_state['brochure']    # Language selection and translate button    st.markdown("### 🌍 Translate Brochure")    targetLanguage = st.selectbox("Select Language", languages)    translateClicked = st.button("Translate Brochure")        if translateClicked:        with st.spinner(f"Translating brochure to {targetLanguage}..."):            try:                translatedStream = translateBrochure(brochure, targetLanguage)                st.session_state['translatedStream'] = translatedStream                    col1, col2 = st.columns(2)                    with col1:                    st.markdown(brochure, unsafe_allow_html=True)                                    with col2:                    streamData(translatedStream, targetLanguage)                                except Exception as e:                st.error(f"Translation failed: {e}")                                                                                                                                                                                                                        